#include <iostream>
#include <numeric>
#include <string>

class Rational {
private:
    int numerator;
    int denominator;

    void simplify() {
        int common = std::gcd(numerator, denominator);
        numerator /= common;
        denominator /= common;
        if (denominator < 0) {
            numerator = -numerator;
            denominator = -denominator;
        }
    }

public:
    Rational(int n = 0, int d = 1) : numerator(n), denominator(d) {
        simplify();
    }

    Rational operator+(const Rational& second) const {
        int n = numerator * second.denominator + denominator * second.numerator;
        int d = denominator * second.denominator;
        return Rational(n, d);
    }

    bool operator<(const Rational& second) const {
        return (numerator * second.denominator) < (second.numerator * denominator);
    }

    std::string toString() const {
        if (denominator == 1) return std::to_string(numerator);
        return std::to_string(numerator) + "/" + std::to_string(denominator);
    }
};

int main() {
    Rational r1(4, 2); // 2/1
    Rational r2(2, 3); // 2/3

    std::cout << "r1 < r2 is " << (r1 < r2 ? "true" : "false") << "\n";
    std::cout << "r2 < r1 is " << (r2 < r1 ? "true" : "false") << "\n";

    Rational r3 = r1 + r2; // 2/1 + 2/3 = 8/3
    std::cout << "r1 + r2 is " << r3.toString() << "\n";

    return 0;
}

#include <iostream>

class Rational {
private:
    int numerator;
    int denominator;

public:
    Rational(int n = 0, int d = 1) : numerator(n), denominator(d) {}

    // Overload [] returning reference to enable Lvalue assignment
    int& operator[](int index) {
        if (index == 0) {
            return numerator;
        } else {
            return denominator;
        }
    }

    double doubleValue() const {
        return static_cast<double>(numerator) / denominator;
    }
};

int main() {
    Rational r(2, 3);

    // Mutate via subscript operator
    r[0] = 5;
    r[1] = 6;

    // Read via subscript operator
    std::cout << "r[0] is " << r[0] << "\n";
    std::cout << "r[1] is " << r[1] << "\n";
    std::cout << "r.doubleValue() is " << r.doubleValue() << "\n";

    return 0;
}

