#include <iostream>
#include <numeric>
#include <string>

class Rational {
private:
    int numerator;
    int denominator;

    void simplify() {
        int common = std::gcd(numerator, denominator);
        numerator /= common;
        denominator /= common;
        if (denominator < 0) {
            numerator = -numerator;
            denominator = -denominator;
        }
    }

public:
    Rational(int n = 0, int d = 1) : numerator(n), denominator(d) {
        simplify();
    }

    // Overload +=
    Rational& operator+=(const Rational& second) {
        numerator = numerator * second.denominator + denominator * second.numerator;
        denominator = denominator * second.denominator;
        simplify();
        return *this;
    }

    std::string toString() const {
        if (denominator == 1) return std::to_string(numerator);
        return std::to_string(numerator) + "/" + std::to_string(denominator);
    }
};

int main() {
    Rational r1(2, 4); // 1/2
    Rational r2 = (r1 += Rational(2, 3)); // 1/2 + 2/3 = 7/6

    std::cout << "r1 is " << r1.toString() << "\n";
    std::cout << "r2 is " << r2.toString() << "\n";

    return 0;
}
